    return ((-2*pow(g3,2)*hbar)/pow(mPhi,2)*EinsSum({Yd,Yu},{{13,14},{11,12}},{i3,i4,i1,i2}) - 4*pow(g3,2)*hbar*EinsSum({LoopFunc({mPhi},3,mubarsq),Yd,Yu},{{},{13,14},{11,12}},{i3,i4,i1,i2}) + (2*pow(g3,2)*hbar*m3*muTilde)/(cgamma*sqrt(1-pow(cgamma,2)))*EinsSum({LoopFunc({m3,mdt,mut,muTilde},101,mubarsq),Yd,Yu},{{14,12},{13,14},{11,12}},{i4,i2,i3,i4,i1,i2}) + (2*pow(g3,2)*hbar*m3*muTilde)/(cgamma*sqrt(1-pow(cgamma,2)))*EinsSum({LoopFunc({m3,mqt,mqt,muTilde},101,mubarsq),Yd,Yu},{{11,13},{13,14},{11,12}},{i1,i3,i3,i4,i1,i2}) + (-5*pow(g1,2)*hbar)/(18*pow(mPhi,2))*EinsSum({Yd,Yu},{{11,14},{13,12}},{i1,i4,i3,i2}) + (-3*pow(g2,2)*hbar)/(2*pow(mPhi,2))*EinsSum({Yd,Yu},{{11,14},{13,12}},{i1,i4,i3,i2}) + (-4*pow(g3,2)*hbar)/(3*pow(mPhi,2))*EinsSum({Yd,Yu},{{11,14},{13,12}},{i1,i4,i3,i2}) + (-5*pow(g1,2)*hbar)/9*EinsSum({LoopFunc({mPhi},3,mubarsq),Yd,Yu},{{},{11,14},{13,12}},{i1,i4,i3,i2}) - 3*pow(g2,2)*hbar*EinsSum({LoopFunc({mPhi},3,mubarsq),Yd,Yu},{{},{11,14},{13,12}},{i1,i4,i3,i2}) + (-8*pow(g3,2)*hbar)/3*EinsSum({LoopFunc({mPhi},3,mubarsq),Yd,Yu},{{},{11,14},{13,12}},{i1,i4,i3,i2}) + (2*pow(g1,2)*hbar*m1*muTilde)/(9*cgamma*sqrt(1-pow(cgamma,2)))*EinsSum({LoopFunc({m1,mdt,mqt,muTilde},101,mubarsq),Yd,Yu},{{14,13},{11,14},{13,12}},{i4,i3,i1,i4,i3,i2}) + (8*pow(g1,2)*hbar*m1*muTilde)/(9*cgamma*sqrt(1-pow(cgamma,2)))*EinsSum({LoopFunc({m1,mdt,mut,muTilde},101,mubarsq),Yd,Yu},{{14,12},{11,14},{13,12}},{i4,i2,i1,i4,i3,i2}) - 0.1111111111111111*(pow(g1,2)*hbar*m1*muTilde)/(cgamma*sqrt(1-pow(cgamma,2)))*EinsSum({LoopFunc({m1,mqt,mqt,muTilde},101,mubarsq),Yd,Yu},{{11,13},{11,14},{13,12}},{i1,i3,i1,i4,i3,i2}) + (-4*pow(g1,2)*hbar*m1*muTilde)/(9*cgamma*sqrt(1-pow(cgamma,2)))*EinsSum({LoopFunc({m1,mqt,mut,muTilde},101,mubarsq),Yd,Yu},{{11,12},{11,14},{13,12}},{i1,i2,i1,i4,i3,i2}) + (3*pow(g2,2)*hbar*m2*muTilde)/(cgamma*sqrt(1-pow(cgamma,2)))*EinsSum({LoopFunc({m2,mqt,mqt,muTilde},101,mubarsq),Yd,Yu},{{11,13},{11,14},{13,12}},{i1,i3,i1,i4,i3,i2}) + (2*pow(g3,2)*hbar*m3*muTilde)/(3*cgamma*sqrt(1-pow(cgamma,2)))*EinsSum({LoopFunc({m3,mdt,mqt,muTilde},101,mubarsq),Yd,Yu},{{14,13},{11,14},{13,12}},{i4,i3,i1,i4,i3,i2}) + (2*pow(g3,2)*hbar*m3*muTilde)/(3*cgamma*sqrt(1-pow(cgamma,2)))*EinsSum({LoopFunc({m3,mdt,mut,muTilde},101,mubarsq),Yd,Yu},{{14,12},{11,14},{13,12}},{i4,i2,i1,i4,i3,i2}) + (2*pow(g3,2)*hbar*m3*muTilde)/(3*cgamma*sqrt(1-pow(cgamma,2)))*EinsSum({LoopFunc({m3,mqt,mqt,muTilde},101,mubarsq),Yd,Yu},{{11,13},{11,14},{13,12}},{i1,i3,i1,i4,i3,i2}) + (2*pow(g3,2)*hbar*m3*muTilde)/(3*cgamma*sqrt(1-pow(cgamma,2)))*EinsSum({LoopFunc({m3,mqt,mut,muTilde},101,mubarsq),Yd,Yu},{{11,12},{11,14},{13,12}},{i1,i2,i1,i4,i3,i2}) + ((1-pow(cgamma,2))*hbar)/(2*pow(cgamma,2)*pow(mPhi,2))*EinsSum({Yd,Yd,Ydc,Yu},{{11,14},{13,2},{1,2},{1,12}},{i1,i4,i3,i2}) + (pow(cgamma,2)*hbar)/(2*(1-pow(cgamma,2))*pow(mPhi,2))*EinsSum({Yd,Yu,Yu,Yuc},{{1,14},{11,2},{13,12},{1,2}},{i4,i1,i3,i2}));
